(() => {
 'use strict';
 const staffWindow=/[?&]workspace=staff(?:&|$)/.test(location.search),$=s=>document.querySelector(s);
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let user=null,secret='',generation=0,timer=null,chat=null,staffToken='',authMode='login',resumeInbox=null,loginResolve=null;
 try{if(!staffWindow)secret=sessionStorage.getItem('sany-customer-session')||'';}catch{}
 function save(token){secret=token;try{if(token)sessionStorage.setItem('sany-customer-session',token);else sessionStorage.removeItem('sany-customer-session');}catch{}}
 async function api(url,body,token=secret){const r=await fetch(url,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json',...(token?{Authorization:`Bearer ${token}`}:{})},...(body===undefined?{}:{body:JSON.stringify(body)})});const data=await r.json();if(!r.ok){const error=new Error(data.error||data.message||'操作失败，请重试。');error.status=r.status;throw error;}return data;}
 /* 聊天文件仅通过当前账号授权接口下载；图片预览使用临时副本，不在地址中携带令牌。 */
 const chatBlobUrls=new Set();
 const pastedFiles=new WeakMap();
 async function chatFiles(input,extra=[]){const files=[...(input?.files||[]),...extra];if(files.length>4)throw Error('一次最多发送4份附件。');return Promise.all(files.map(file=>{if(file.size>4*1024*1024)throw Error('每份附件不能超过4 MB。');return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({name:file.name,data:String(reader.result).split(',')[1]});reader.onerror=()=>reject(Error('附件读取失败。'));reader.readAsDataURL(file);});}));}
 function renderPending(form){const host=form?.querySelector('.cu-pending-files');if(!host)return;const pasted=pastedFiles.get(form)||[],selected=[...(form.elements.files?.files||[])],names=[...selected,...pasted].map(file=>file.name);host.hidden=!names.length;host.innerHTML=names.length?`<span>待发送：${names.map(esc).join('、')}</span>${pasted.length?'<button type="button" class="btn" data-cu="clear-pasted">移除粘贴图片</button>':''}`:'';}
 function addPasted(form,files){const current=pastedFiles.get(form)||[],selected=form.elements.files?.files?.length||0;if(selected+current.length+files.length>4)throw Error('一次最多发送4份附件。');const normalized=files.map((file,index)=>file.name?file:new File([file],`粘贴图片-${Date.now()}-${index+1}.${file.type==='image/jpeg'?'jpg':file.type==='image/webp'?'webp':'png'}`,{type:file.type||'image/png'}));pastedFiles.set(form,[...current,...normalized]);renderPending(form);}
 async function chatFileBlob(id,token){const response=await fetch('/api/files/'+encodeURIComponent(id),{headers:{Authorization:'Bearer '+token}});if(!response.ok)throw Error('无法访问此附件，请重新登录后重试。');return response.blob();}
 function messageFiles(message,element,context){for(const file of message.files||[]){const button=document.createElement('button');button.type='button';button.className='cu-file';button.dataset.cu='chat-file';button.dataset.id=file.id;button.dataset.name=file.name||file.filename||'订单附件';button.textContent='▤ '+button.dataset.name;element.append(button);if(String(file.mime||'').startsWith('image/'))void chatFileBlob(file.id,context.token).then(blob=>{if(chat!==context||!element.isConnected||!blob.type.startsWith('image/'))return;const url=URL.createObjectURL(blob);chatBlobUrls.add(url);const image=document.createElement('img');image.className='cu-chat-image';image.alt=button.dataset.name;image.src=url;element.append(image);}).catch(()=>{});}}
 function identity(){if(staffWindow)return;const host=$('#identity');if(!host)return;let wrap=host.querySelector('[data-customer-entry]');if(!wrap){wrap=document.createElement('div');wrap.dataset.customerEntry='';wrap.className='cu-profile';const badge=host.querySelector('.pill');if(badge)badge.after(wrap);else host.prepend(wrap);}wrap.innerHTML=`<button type="button" class="window-switch cu-profile-button" data-cu="profile-menu" aria-label="${user?'我的账号':'客户登录'}" title="${user?'我的账号':'客户登录'}" aria-expanded="false"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/></svg></button><div class="cu-profile-menu" hidden><button type="button" data-cu="profile-password">修改密码</button><button type="button" data-cu="logout">退出账号</button></div>`;}
 function closeProfile(){const menu=$('.cu-profile-menu');if(menu)menu.hidden=true;$('.cu-profile-button')?.setAttribute('aria-expanded','false');}
 function passwordDialog(){closeProfile();let d=$('#customerPassword');if(!d){d=document.createElement('dialog');d.id='customerPassword';d.className='cu-password-dialog';d.innerHTML='<div class="cu-dialog-head"><h2>修改密码</h2><button type="button" data-cu="password-close" aria-label="关闭修改密码">关闭</button></div><form data-cu-form="password"><label class="field">原密码<input type="password" name="currentPassword" autocomplete="current-password" required></label><label class="field">新密码<input type="password" name="password" autocomplete="new-password" minlength="10" maxlength="200" required></label><label class="field">确认新密码<input type="password" name="repeat" autocomplete="new-password" minlength="10" maxlength="200" required></label><div class="form-error" role="alert"></div><button class="btn primary" type="submit">修改密码并重新登录</button></form>';document.body.append(d);}d.querySelector('form').reset();d.querySelector('.form-error').textContent='';d.showModal();}
 document.addEventListener('click',e=>{if(!e.target.closest('.cu-profile'))closeProfile();});
 document.addEventListener('keydown',e=>{if(e.key==='Escape')closeProfile();});
 function stop(keepDialog=false){chatBlobUrls.forEach(url=>URL.revokeObjectURL(url));chatBlobUrls.clear();resumeInbox=null;generation++;clearTimeout(timer);timer=null;chat=null;const d=$('#customerChat');if(d?.open&&!keepDialog)d.close();}
 function dialog(){let d=$('#customerChat');if(!d){d=document.createElement('dialog');d.id='customerChat';d.setAttribute('aria-labelledby','customerChatTitle');d.innerHTML='<div class="cu-dialog-head"><h2 id="customerChatTitle">在线客服</h2><button type="button" data-cu="close" aria-label="关闭在线客服">关闭</button></div><div id="customerChatBody"></div>';d.addEventListener('close',()=>{if(loginResolve){const resolve=loginResolve;loginResolve=null;resolve(false);}generation++;clearTimeout(timer);chat=null;if(staffWindow&&staffToken&&document.querySelector('#workBody .cu-inbox'))void staff(document.querySelector('#workBody'),'customer-chat',staffToken);});document.body.append(d);}return d;}
 /* 游客可看到客服入口；点击后先说明登录要求，由用户决定是否前往账号页。 */
 function chatLoginPrompt(){const d=dialog();if(!d.open)d.showModal();$('#customerChatBody').innerHTML='<div class="cu-login-prompt"><p>登录客户账号后即可咨询在线客服，并查看工作人员的回复。</p><div class="actions"><button type="button" class="btn primary" data-cu="chat-login">去登录</button><button type="button" class="btn" data-cu="close">暂不登录</button></div></div>';}
 const returnKey='sany-login-return';
 function rememberReturn(action){const hash=location.hash||'#catalog';if(!['#catalog','#projects','#customer'].includes(hash))return;try{sessionStorage.setItem(returnKey,JSON.stringify({hash,action:action||null,scrollY:window.scrollY,at:Date.now()}));}catch{}}
 function takeReturn(){try{const value=JSON.parse(sessionStorage.getItem(returnKey)||'null');sessionStorage.removeItem(returnKey);if(value&&Date.now()-value.at<900000&&['#catalog','#projects','#customer'].includes(value.hash))return value;}catch{}return null;}
 document.addEventListener('click',e=>{if(!secret&&e.target.closest('a[href="#account"]'))rememberReturn();},true);
 window.addEventListener('hashchange',()=>{if(location.hash!=='#account'){try{sessionStorage.removeItem(returnKey);}catch{}}});
 async function requireLogin(action){if(secret){try{const r=await api('/api/customer/me');user=r.customer;identity();return true;}catch(e){if(e.status!==401&&e.status!==403)throw e;save('');user=null;identity();}}rememberReturn(action);stop();authMode='login';if(location.hash!=='#account')location.hash='account';else authView();return false;}
 function authHTML(){return `<h2>${authMode==='register'?'手机号注册':'手机号登录'}</h2><div class="actions"><button class="btn" type="button" data-cu="login">登录</button><button class="btn" type="button" data-cu="register">注册</button></div><form data-cu-form="auth" autocomplete="off"><label class="field"><span>手机号</span><input name="phone" type="tel" inputmode="tel" autocomplete="off" autocapitalize="off" spellcheck="false" data-lpignore="true" data-1p-ignore maxlength="30" required></label><label class="field"><span>密码（至少10位）</span><input name="password" type="password" autocomplete="new-password" data-lpignore="true" data-1p-ignore minlength="10" maxlength="200" required></label>${authMode==='register'?'<label class="field"><span>确认密码</span><input name="repeat" type="password" autocomplete="new-password" data-lpignore="true" data-1p-ignore minlength="10" maxlength="200" required></label>':''}<p class="privacy-note">本机参赛账号，未接短信验证；请使用演示手机号和专用密码。客户账号不能进入工作人员后台。</p><div class="form-error" role="alert"></div><button class="btn primary" type="submit">${authMode==='register'?'注册并登录':'登录'}</button></form>`;}
 /* 登录页每次挂载都从空表单开始。浏览器凭据回填通常发生在渲染后的数帧内；
  * 一旦检测到真实键盘、粘贴或 beforeinput，就停止自动清空，不能误删用户正在输入的内容。 */
 function prepareAuthForm(){const form=$('[data-cu-form="auth"]');if(!form)return;const fields=[...form.querySelectorAll('input')];const markEdited=event=>{if(event.isTrusted)form.dataset.userEdited='true';};form.addEventListener('beforeinput',markEdited,true);form.addEventListener('keydown',markEdited,true);form.addEventListener('paste',markEdited,true);const clear=()=>{if(!form.isConnected||form.dataset.userEdited==='true')return;form.reset();fields.forEach(input=>{input.value='';});};form.addEventListener('focusin',clear,true);clear();requestAnimationFrame(()=>{clear();requestAnimationFrame(clear);});setTimeout(clear,200);setTimeout(clear,700);}
 function authView(){const d=$('#customerChat');if(d?.open)d.close();const host=$('#main');host.innerHTML=`<section class="wrap"><div class="section-top"><div><p class="eyebrow">CUSTOMER ACCOUNT</p><h1>我的账号</h1><p>登录后办理询价租购、项目需求和售后服务。</p></div></div><article class="panel cu-account">${authHTML()}</article></section>`;prepareAuthForm();}
 function accountRecords(rows,includeProjects=true,showFilters=true){
  const labels={submitted:'待受理',confirmed:'报价已确认',preparing:'备货中',shipped:'已发运',delivered:'已交付',cancelled:'已取消',reviewing:'审核中',needs_info:'待补充资料',accepted:'方案已确认',closed:'已关闭'};
  const type=r=>r.kind==='project'?'project':r.mode==='rent'?'rent':'buy';
  return `${showFilters?`<div class="actions cu-record-filters" aria-label="业务分类">${[['all','全部'],['buy','购买订单'],['rent','租赁订单'],['project','项目需求']].filter(([key])=>includeProjects||key!=='project').map(([key,label])=>`<button class="btn ${key==='all'?'primary':''}" data-cu="filter-records" data-filter="${key}" aria-pressed="${key==='all'}">${label}（${rows.filter(r=>key==='all'||type(r)===key).length}）</button>`).join('')}</div>`:''}<div class="cu-record-list">${rows.map(r=>`<article class="record" data-record-type="${type(r)}"><div class="record-main"><h3 class="cu-record-heading"><span>${esc(r.title)}</span><strong class="cu-order-status cu-status-${esc(r.status)}">${esc(labels[r.status]||r.status)}</strong></h3><p>${r.kind==='project'?'售前项目需求':r.mode==='rent'?'租赁订单':'购买订单'} · ${esc(r.number)}</p><p>提交时间：${esc(new Date(r.createdAt).toLocaleString('zh-CN'))}${r.quantity?' · 数量：'+esc(r.quantity)+' 台':''}</p></div><button type="button" class="btn" data-cu="record" data-id="${esc(r.id)}" data-kind="${esc(r.kind)}">查看进度</button><button type="button" class="btn cu-record-chat" data-cu="record-chat" data-id="${esc(r.id)}" data-kind="${esc(r.kind)}">联系客服<span class="cu-unread" hidden></span></button></article>`).join('')}<p class="cu-record-empty" ${rows.length?'hidden':''}>暂无此类记录，可前往设备租购或项目需求提交。</p></div>`;
 }
 async function orders(host){stop();host.innerHTML='<section class="wrap"><h1>订单与售后</h1><p>登录后查看您的订单和售后工单。</p><a class="btn" href="#account">登录 / 注册</a></section>';if(!await requireLogin()||location.hash!=='#customer')return;const epoch=generation;try{const [data,after]=await Promise.all([api('/api/customer/records'),api('/api/customer/after-sales')]);if(epoch!==generation)return;const rows=data.records.filter(r=>r.kind==='order'),labels={submitted:'待受理',assigned:'已派单',in_progress:'维修中',pending_review:'待审核',awaiting_customer:'待客户验收',closed:'已完成'};host.innerHTML=`<section class="wrap"><div class="section-top"><div><p class="eyebrow">MY ORDERS & AFTER-SALES</p><h1>订单与售后</h1><p>查看租购进度、申请售后并跟进维修服务。</p></div><button class="btn" data-cu="orders-refresh">刷新记录</button></div><div class="tabs" aria-label="订单分类">${[['buy','购买订单'],['rent','租赁订单']].map(([mode,label])=>`<button type="button" class="${mode==='buy'?'active':''}" data-cu="order-section" data-section="${mode}" aria-pressed="${mode==='buy'}">${label}（${rows.filter(r=>r.mode===mode).length}）</button>`).join('')}<button type="button" data-cu="order-section" data-section="after-sales" aria-pressed="false">售后订单（${after.tickets.length}）</button></div>${['buy','rent'].map(mode=>`<article class="panel" data-order-panel="${mode}" ${mode==='buy'?'':'hidden'}>${accountRecords(rows.filter(r=>r.mode===mode),false,false)}<p class="muted">已交付订单可申请售后；发运后请先在订单详情中确认收货。</p>${rows.filter(r=>r.mode===mode&&r.status==='delivered').map(r=>`<div class="record"><span>${esc(r.title)} · ${esc(r.number)}</span><button class="btn" data-cu="after-create" data-id="${esc(r.id)}">申请售后</button></div>`).join('')}</article>`).join('')}<article class="panel" data-order-panel="after-sales" hidden>${after.tickets.map(t=>`<div class="record"><div class="record-main"><h3 class="cu-record-heading"><span>${esc(t.title)}</span><strong class="cu-order-status cu-status-${esc(t.status)}">${esc(labels[t.status]||t.status)}</strong></h3><p>${esc(t.issue)}</p><p>${esc(t.number||t.id)} · ${esc(new Date(t.createdAt).toLocaleString())}</p></div><button class="btn" data-cu="after-detail" data-id="${esc(t.id)}" data-order="${esc(t.orderId)}">查看售后进度</button><button type="button" class="btn cu-record-chat" data-cu="record-chat" data-id="${esc(t.orderId)}" data-kind="order">联系客服<span class="cu-unread" hidden></span></button></div>`).join('')||'<p>暂无售后工单，可从已交付订单申请售后。</p>'}</article></section>`;}catch(e){if(epoch===generation)host.innerHTML=`<section class="wrap"><p>${esc(e.message)}</p><button class="btn" data-cu="orders-refresh">重试</button></section>`;}}
 async function account(host){stop();identity();if(!secret){authView();return;}const epoch=generation;host.innerHTML='<section class="wrap"><p>正在读取客户账号…</p></section>';try{const [me,records]=await Promise.all([api('/api/customer/me'),api('/api/customer/records')]);if(epoch!==generation)return;user=me.customer;identity();host.innerHTML=`<section class="wrap"><div class="section-top"><div><p class="eyebrow">CUSTOMER ACCOUNT</p><h1>我的客户账号</h1><p>${esc(user.phone)} · 客户账号</p></div><div class="cu-account-tools"><details class="cu-password"><summary>修改密码</summary><form data-cu-form="password"><label class="field">原密码<input type="password" name="currentPassword" autocomplete="current-password" required></label><label class="field">新密码<input type="password" name="password" autocomplete="new-password" minlength="10" maxlength="200" required></label><label class="field">确认新密码<input type="password" name="repeat" autocomplete="new-password" minlength="10" maxlength="200" required></label><div class="form-error" role="alert"></div><button class="btn" type="submit">修改密码并重新登录</button></form></details><button type="button" class="btn" data-cu="logout">退出客户账号</button></div></div><div class="panel"><div class="section-top"><h2>我的订单与需求</h2><button class="btn" data-cu="account-retry">刷新记录</button></div><p class="muted">集中查看您的购买、租赁订单和项目需求，包含当前手机号提交的未绑定历史记录。</p>${accountRecords(records.records)}<div class="actions"><a class="btn" href="#catalog">设备租购</a><a class="btn" href="#projects">项目需求</a><button class="btn" data-cu="chat">联系在线客服</button></div></div></section>`;}catch(e){if(epoch!==generation)return;if(e.status===401||e.status===403){save('');user=null;identity();authView();}else host.innerHTML=`<section class="wrap"><p>${esc(e.message)}</p><button class="btn" data-cu="account-retry">重试</button></section>`;}}
 async function openChat(id,token){if(!staffWindow&&!secret){chatLoginPrompt();return;}if(!staffWindow&&!await requireLogin({type:'chat'}))return;stop(true);const d=dialog();if(!d.open)d.showModal();const host=$('#customerChatBody');host.innerHTML='<p>正在连接客服会话…</p>';const epoch=generation;
  if(!staffWindow&&!secret){chatLoginPrompt();return;}
  try{if(!id)id=(await api('/api/customer/chat',{})).chat.id;if(epoch!==generation||!d.open)return;chat={id,token:token||secret,after:0,messages:[]};host.innerHTML='<p class="privacy-note">本机客户与工作人员聊天，消息约1.5秒更新。工作人员将在工作台回复；请勿发送密码或敏感资料。</p><div class="cu-messages" role="log" aria-label="在线客服消息" aria-live="polite"></div><p id="cuChatStatus" class="muted" role="status"></p><form data-cu-form="message" class="cu-composer"><div class="cu-chat-tools"><label class="cu-chat-tool" title="选择图片或文件"><input class="cu-file-input" type="file" name="files" multiple accept=".pdf,.docx,.png,.jpg,.jpeg,.webp"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3.5 6.5h6l2 2h9v10h-17zM3.5 6.5v-2h6l2 2h9v2"/></svg><span>文件</span></label><span>可直接粘贴截图</span></div><div class="cu-pending-files" hidden></div><textarea name="text" rows="3" maxlength="2000" aria-label="消息内容" placeholder="输入消息；也可以在这里粘贴图片…"></textarea><div class="cu-send-row"><small>Enter 发送 · Shift + Enter 换行</small><div class="form-error" role="alert"></div><button type="submit" class="btn primary">发送消息</button></div></form>';await poll(epoch);}catch(e){if(epoch===generation&&!staffWindow&&(e.status===401||e.status===403)){save('');user=null;identity();location.hash='account';return;}if(epoch===generation)host.innerHTML=`<p>${esc(e.message)}</p><button class="btn" data-cu="${staffWindow?'close':'chat'}">${staffWindow?'关闭':'重新连接'}</button>`;}}
 async function poll(epoch){if(epoch!==generation||!chat||document.hidden||chat.polling)return;clearTimeout(timer);const context=chat;context.polling=true;try{const data=await api(`/api/customer/chats/${context.id}/messages?after=${context.after}`,undefined,context.token);if(epoch!==generation||chat!==context)return;if(data.messages.length){const log=$('.cu-messages'),bottom=log.scrollHeight-log.scrollTop-log.clientHeight<60;context.messages.push(...data.messages);context.after=data.messages.at(-1).seq;for(const m of data.messages){const el=document.createElement('article');el.className='cu-message '+(m.sender===(staffWindow?'staff':'customer')?'mine':'');el.innerHTML=`<small>${esc(m.senderName)} · ${esc(new Date(m.at).toLocaleTimeString())}</small><p>${esc(m.text)}</p>`;log.append(el);messageFiles(m,el,context);}if(bottom)log.scrollTop=log.scrollHeight;}if(!document.hidden&&$('#customerChat')?.open&&context.after)await api(`/api/customer/chats/${context.id}/read`,{seq:context.after},context.token);$('#cuChatStatus').textContent=context.messages.length?'聊天记录已同步':'可以开始咨询，发送后由工作人员回复。';}catch(e){if(epoch!==generation)return;$('#cuChatStatus').textContent=e.message;if(e.status===401||e.status===403)return;}context.polling=false;if(epoch===generation)timer=setTimeout(()=>void poll(epoch),1500);}
 async function staff(host,tab,token){stop();staffToken=token;const epoch=generation;host.innerHTML='<p>正在加载…</p>';async function refresh(){if(epoch!==generation||!host.isConnected||document.hidden)return;try{const data=await api(tab==='customers'?'/api/customer/accounts':'/api/customer/chats',undefined,token);if(epoch!==generation||!host.isConnected)return;host.innerHTML=tab==='customers'?`<article class="panel"><h2>客户账号管理</h2><p>客户手机号账号与员工账号独立；停用会立即撤销客户登录会话。</p><div class="table-wrap"><table><thead><tr><th>手机号</th><th>注册时间</th><th>状态</th><th>操作</th></tr></thead><tbody>${data.customers.map(c=>`<tr><td>${esc(c.phone)}</td><td>${esc(new Date(c.createdAt).toLocaleString())}</td><td>${c.active?'正常':'已停用'}</td><td><button class="btn" data-cu="toggle" data-id="${esc(c.id)}" data-active="${!c.active}">${c.active?'停用':'启用'}</button></td></tr>`).join('')||'<tr><td colspan="4">暂无注册客户</td></tr>'}</tbody></table></div><p id="cuAdminStatus" role="status"></p></article>`:`<article class="panel"><p class="muted">接待客户从首页悬浮按钮发起的咨询，不要求客户先下单。点击会话回复。</p>${data.chats.map(c=>`<button type="button" class="cu-inbox" data-cu="staff-chat" data-id="${esc(c.id)}"><strong>${esc(c.phone)}<span class="cu-unread" ${c.unread?'':'hidden'}>${c.unread||0}</span></strong><span>${esc(c.lastMessage||'新咨询，等待消息')}</span><small>${esc(new Date(c.updatedAt).toLocaleString())} · ${c.count} 条消息</small></button>`).join('')||'<p>暂无咨询会话。</p>'}</article>`;}catch(e){if(epoch===generation)host.innerHTML=`<p>${esc(e.message)}</p>`;}if(epoch===generation&&tab!=='customers')timer=setTimeout(refresh,1500);}resumeInbox=refresh;await refresh();}
 document.addEventListener('click',async e=>{const b=e.target.closest('[data-cu]');if(!b)return;const action=b.dataset.cu;try{
  if(action==='profile-menu'){if((!secret||!user)&&!await requireLogin())return;const menu=$('.cu-profile-menu');menu.hidden=!menu.hidden;$('.cu-profile-button').setAttribute('aria-expanded',String(!menu.hidden));}
  else if(action==='profile-password'){if(await requireLogin())passwordDialog();}
  else if(action==='password-close')$('#customerPassword')?.close();
  else if(action==='close')stop();else if(action==='chat')await openChat();else if(action==='chat-file'){if(!chat)throw Error('会话已关闭。');const blob=await chatFileBlob(b.dataset.id,chat.token),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=b.dataset.name||'订单附件';link.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}else if(action==='clear-pasted'){const form=b.closest('[data-cu-form="message"]');if(form){pastedFiles.delete(form);renderPending(form);}}else if(action==='chat-login')await requireLogin({type:'chat'});else if(action==='login'||action==='register'){authMode=action;authView();}
  else if(action==='logout'){const previous=secret;save('');user=null;stop();identity();authView();await api('/api/customer/logout',{},previous).catch(()=>{});}
  else if(action==='filter-records'){const key=b.dataset.filter;document.querySelectorAll('.cu-record-filters button').forEach(el=>{const active=el===b;el.classList.toggle('primary',active);el.setAttribute('aria-pressed',String(active));});let count=0;document.querySelectorAll('[data-record-type]').forEach(el=>{el.hidden=key!=='all'&&el.dataset.recordType!==key;if(!el.hidden)count++;});$('.cu-record-empty').hidden=count>0;}
  else if(action==='order-section'){document.querySelectorAll('[data-cu="order-section"]').forEach(el=>{const active=el===b;el.classList.toggle('active',active);el.setAttribute('aria-pressed',String(active));});document.querySelectorAll('[data-order-panel]').forEach(el=>el.hidden=el.dataset.orderPanel!==b.dataset.section);}
  else if(action==='orders-refresh')await orders($('#main'));
  else if(action==='after-create'){const r=await api('/api/customer/record',{kind:'order',id:b.dataset.id});await window.SanyStartAfterSales(b.dataset.id,r.token);}
  else if(action==='after-detail'){const r=await api('/api/customer/record',{kind:'order',id:b.dataset.order});await window.SanyOpenCustomerTicket(b.dataset.id,r.token);}
  else if(action==='account-retry')await account($('#main'));
  else if(action==='record-chat'){const r=await api('/api/customer/record',{kind:b.dataset.kind,id:b.dataset.id});await window.SanyOpenCustomerConversation(b.dataset.kind,b.dataset.id,r.token);}
  else if(action==='record'){const r=await api('/api/customer/record',{kind:b.dataset.kind,id:b.dataset.id});location.hash='receipt='+encodeURIComponent(r.accessKey);}
  else if(action==='staff-chat')await openChat(b.dataset.id,staffToken);
  else if(action==='toggle'){b.disabled=true;await api('/api/customer/accounts/'+b.dataset.id,{active:b.dataset.active==='true'},staffToken);await staff($('#workBody'),'customers',staffToken);}
 }catch(error){const status=$('#cuAdminStatus')||$('#cuChatStatus');if(status)status.textContent=error.message;else{const d=dialog();if(!d.open)d.showModal();$('#customerChatBody').textContent=error.message;}}finally{b.disabled=false;}});
 document.addEventListener('change',event=>{const form=event.target.closest('[data-cu-form="message"]');if(form&&event.target.matches('input[type="file"]'))renderPending(form);});
 /* 图片粘贴只在聊天输入区生效；文字粘贴不拦截，仍进入文本框。 */
 document.addEventListener('paste',event=>{const form=event.target.closest('[data-cu-form="message"]');if(!form)return;const images=[...(event.clipboardData?.items||[])].filter(item=>item.kind==='file'&&item.type.startsWith('image/')).map(item=>item.getAsFile()).filter(Boolean);if(!images.length)return;event.preventDefault();try{addPasted(form,images);$('#cuChatStatus').textContent=`已粘贴 ${images.length} 张图片，发送前可继续输入说明。`;}catch(error){$('#cuChatStatus').textContent=error.message;}});
 document.addEventListener('keydown',event=>{const field=event.target.closest('[data-cu-form="message"] textarea[name="text"]');if(!field||event.key!=='Enter'||event.shiftKey||event.isComposing)return;event.preventDefault();field.form.requestSubmit();});
 document.addEventListener('submit',async e=>{const form=e.target.closest('[data-cu-form]');if(!form)return;e.preventDefault();const button=form.querySelector('[type="submit"]'),error=form.querySelector('.form-error');if(button.disabled)return;button.disabled=true;error.textContent='';const data=Object.fromEntries(new FormData(form)),epoch=generation;try{
  if(form.dataset.cuForm==='auth'){const r=await api('/api/customer/'+authMode,data,'');if(epoch!==generation){await api('/api/customer/logout',{},r.token).catch(()=>{});return;}save(r.token);user=r.customer;identity();if(loginResolve){const resolve=loginResolve;loginResolve=null;stop();resolve(true);return;}const destination=takeReturn();if(destination&&window.SanyResumeCustomer)await window.SanyResumeCustomer(destination);else await account($('#main'));}
  else if(form.dataset.cuForm==='password'){await api('/api/customer/password',data);if(epoch!==generation)return;$('#customerPassword')?.close();save('');user=null;identity();await requireLogin();}
  else if(form.dataset.cuForm==='message'){if(!chat)throw Error('会话已关闭，请重新连接。');const pasted=pastedFiles.get(form)||[],signature=JSON.stringify([data.text,...[...(form.elements.files?.files||[]),...pasted].map(f=>[f.name,f.size,f.lastModified])]);if(form.dataset.message!==signature){form.dataset.message=signature;form.dataset.request=window.SanyRequestId.create();}const context=chat,files=await chatFiles(form.elements.files,pasted);if(!String(data.text||'').trim()&&!files.length)throw Error('请输入消息或选择附件。');await api(`/api/customer/chats/${context.id}/messages`,{text:data.text||'',files,requestId:form.dataset.request},context.token);if(epoch!==generation||chat!==context)return;form.reset();pastedFiles.delete(form);renderPending(form);delete form.dataset.request;delete form.dataset.message;await poll(epoch);}
 }catch(e){if(epoch===generation&&error.isConnected)error.textContent=e.message;}finally{button.disabled=false;}});
 document.addEventListener('visibilitychange',()=>{if(document.hidden)clearTimeout(timer);else if(chat)void poll(generation);else if(resumeInbox)void resumeInbox();});
 let notificationBusy=false;
 function badge(button,count){if(!button)return;let dot=button.querySelector('.cu-unread');if(!dot){dot=document.createElement('span');dot.className='cu-unread';button.append(dot);}dot.hidden=!count;dot.textContent=count>99?'99+':String(count);dot.setAttribute('aria-label',`${count}条未读客服消息`);}
 async function notifications(){if(staffWindow||document.hidden||notificationBusy)return;if(!secret){document.querySelectorAll('.cu-unread').forEach(el=>el.hidden=true);return;}notificationBusy=true;const token=secret;try{const data=await api('/api/customer/notifications',undefined,token);if(token!==secret)return;document.querySelectorAll('[data-cu="chat"]').forEach(b=>badge(b,data.supportUnread));document.querySelectorAll('[data-cu="record-chat"]').forEach(b=>badge(b,data.records.find(r=>r.id===b.dataset.id&&r.kind===b.dataset.kind)?.unread||0));document.querySelectorAll('[data-cu="order-section"]').forEach(b=>{const panel=document.querySelector(`[data-order-panel="${b.dataset.section}"]`);const keys=new Set();let total=0;panel?.querySelectorAll('[data-cu="record-chat"]').forEach(link=>{const key=link.dataset.kind+':'+link.dataset.id;if(keys.has(key))return;keys.add(key);total+=data.records.find(r=>r.id===link.dataset.id&&r.kind===link.dataset.kind)?.unread||0;});badge(b,total);});}catch{}finally{notificationBusy=false;}}
 if(!staffWindow){setInterval(notifications,2000);document.addEventListener('visibilitychange',()=>void notifications());}
 window.SanyCustomers={requireLogin,token:()=>staffWindow?'':secret,identity,account,orders,staff,stop,openChat};
 if(!staffWindow){const button=document.createElement('button');button.type='button';button.className='cu-floating';button.dataset.cu='chat';button.setAttribute('aria-label','打开在线客服');button.innerHTML='<span aria-hidden="true">◌</span><b>在线客服</b>';document.body.append(button);if(secret){const initial=secret;void api('/api/customer/me').then(r=>{if(secret===initial){user=r.customer;identity();}}).catch(e=>{if(secret===initial&&(e.status===401||e.status===403)){save('');user=null;identity();}});}}
})();
